src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The most common value is the background; matching non-background markers
    # bound straight line segments, which are colored 3.
    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    marker_colors = {value for row in grid for value in row if value != background}
    for color in marker_colors:
        for r in range(h):
            marks = [c for c, value in enumerate(grid[r]) if value == color]
            for a, b in zip(marks, marks[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
        for c in range(w):
            marks = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(marks, marks[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out
'''
